import 'dart:io';
import 'package:path_provider/path_provider.dart';

class CacheService {
  /// Clears temporary cache files generated by image cropping and document scanning
  static Future<void> clearTempCache() async {
    try {
      final tempDir = await getTemporaryDirectory();
      if (tempDir.existsSync()) {
        final List<FileSystemEntity> files = tempDir.listSync(recursive: true);
        final now = DateTime.now();

        for (final file in files) {
          if (file is File) {
            try {
              final lastModified = await file.lastModified();
              if (now.difference(lastModified).inHours >= 1 ||
                  file.path.contains('image_cropper') ||
                  file.path.contains('ucrop') ||
                  file.path.contains('scaled_')) {
                await file.delete();
              }
            } catch (_) {}
          }
        }
      }
    } catch (_) {}
  }
}
